var instances_q17 = [].concat(
  // q17 :- lineitem(_,_,P,_,_,_,_,_,_,_,_,_,_), q17_part(P).
  (function() {
    return _.flatten(map(function(e1) {
      var P = e1.t[2];
      return _.flatten(map(function(e2) {
        return [['q17', [], and([e1.v, e2.v])]];
      }, probe(q17_part, [P])));
    }, _.values(lineitem)));
  })()
);
var q17 = relation({}, instances_q17);

